tape( 'if provided two arguments, the method returns a typed array containing elements starting from a specified beginning index (inclusive) and ending at a specified stop index (exclusive) (complex128)', function test( t ) {
	var Complex128Array;
	var expected;
	var actual;
	var arr;

	Complex128Array = factory( 'complex128' );

	arr = new Complex128Array( [ 1.0, -1.0, 2.0, -2.0, 3.0, -3.0, 4.0, -4.0 ] );
	expected = new Float64Array( [ 2.0, -2.0, 3.0, -3.0 ] );
	actual = arr.slice( 1, 3 );

	t.strictEqual( instanceOf( actual, Complex128Array ), true, 'returns expected value' );
	t.strictEqual( actual.length, expected.length/2, 'returns expected value' );
	t.deepEqual( reinterpret128( actual, 0 ), expected, 'returns expected value' );

	arr = new Complex128Array( [ 1.0, -1.0, 2.0, -2.0, 3.0, -3.0, 4.0, -4.0 ] );
	expected = new Float64Array( [ 2.0, -2.0, 3.0, -3.0, 4.0, -4.0 ] );
	actual = arr.slice( 1, 30 );

	t.strictEqual( instanceOf( actual, Complex128Array ), true, 'returns expected value' );
	t.strictEqual( actual.length, expected.length/2, 'returns expected value' );
	t.deepEqual( reinterpret128( actual, 0 ), expected, 'returns expected value' );
	t.end();
});

